package com.bank.qa.tdd;

import java.math.BigDecimal;
import java.math.RoundingMode;

// This class was written ONLY to make the tests below pass (Green),
// then refactored for clarity (Refactor) without changing behavior.
class InterestCalculator {
    // simple interest = principal * rate% * years
    BigDecimal simpleInterest(BigDecimal principal, BigDecimal ratePct, int years) {
        if (principal == null || ratePct == null)            // edge driven by a test
            throw new IllegalArgumentException("principal/rate required");
        if (principal.signum() < 0 || ratePct.signum() < 0 || years < 0)
            throw new IllegalArgumentException("non-negative values required");
        return principal
            .multiply(ratePct).divide(new BigDecimal("100"))
            .multiply(BigDecimal.valueOf(years))
            .setScale(2, RoundingMode.HALF_UP);
    }
}
