package com.bank.qa.tdd;

import java.math.BigDecimal;
import java.util.logging.*;

// Plays out the Red-Green-Refactor cycle as a runnable narrative.
public class TddDemo {
    private static final Logger log = Logger.getLogger(TddDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new TddLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    private static void check(String name, boolean passed) {
        log.info((passed ? "GREEN " : "RED ") + name);
    }

    public static void main(String[] args) {
        log.info("=== RED: write the test FIRST; it would fail with no calculator ===");
        log.info("Test: SI(100000, 4%, 1yr) expected 4000.00  (fails before code exists)");

        log.info("=== GREEN: minimal code makes the test pass ===");
        InterestCalculator calc = new InterestCalculator();
        check("SI(100000,4%,1) == 4000.00",
            calc.simpleInterest(new BigDecimal("100000"), new BigDecimal("4"), 1)
                .compareTo(new BigDecimal("4000.00")) == 0);

        log.info("=== Add next behavior (another RED->GREEN): multi-year ===");
        check("SI(100000,4%,3) == 12000.00",
            calc.simpleInterest(new BigDecimal("100000"), new BigDecimal("4"), 3)
                .compareTo(new BigDecimal("12000.00")) == 0);

        log.info("=== Edge driven by a test: negative principal rejected ===");
        boolean threw = false;
        try { calc.simpleInterest(new BigDecimal("-1"), new BigDecimal("4"), 1); }
        catch (IllegalArgumentException e) { threw = true; }
        check("negative principal throws", threw);

        log.info("=== REFACTOR: cleaned math/scale with tests still GREEN (behavior unchanged) ===");
        check("still SI(100000,4%,1) == 4000.00",
            calc.simpleInterest(new BigDecimal("100000"), new BigDecimal("4"), 1)
                .compareTo(new BigDecimal("4000.00")) == 0);

        log.info("Tests now DOCUMENT the interest rules as executable specifications.");
    }
}

// ─── Would be in TddLogFormatter.java in a real project ───
class TddLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
